```cpp
#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        int64 n;
        int m;
        cin >> n >> m;
        vector<int64> a(m + 1);
        for (int i = 1; i <= m; ++i) cin >> a[i];

        // 预处理：按 keyL = a_t + t 排序，同时存储 keyR = a_t - t
        struct Node {
            int64 keyL, keyR;
            int t;
        };
        vector<Node> v;
        v.reserve(m);
        for (int i = 1; i <= m; ++i) {
            v.push_back({a[i] + i, a[i] - i, i});
        }
        sort(v.begin(), v.end(), [](const Node& A, const Node& B) {
            return A.keyL < B.keyL;
        });

        // 判定第 TT 个时刻结束时是否全亮
        auto ok = [&](int64 TT) -> bool {
            if (TT <= 0) return false;
            int64 cur = 1;
            for (auto& nd : v) {
                if (nd.t > TT) continue;           // 尚未手动点亮
                int64 L = nd.keyL - TT;            // (a_t + t) - TT
                int64 R = nd.keyR + TT;            // (a_t - t) + TT
                if (R < 1 || L > n) continue;     // 与 [1,n] 无交
                if (L < 1) L = 1;
                if (R > n) R = n;
                if (L > cur) return false;        // 出现空档
                if (R + 1 > cur) cur = R + 1;
                if (cur > n) return true;         // 全覆盖
            }
            return cur > n;
        };

        int64 lo = 0, hi = n + m;
        while (lo < hi) {
            int64 mid = (lo + hi) >> 1;
            if (ok(mid))
                hi = mid;
            else
                lo = mid + 1;
        }
        cout << lo << "\n";
    }
    return 0;
}
